export declare const bauhausTheme = "/* \u5305\u8C6A\u65AF\u98CE\u683C */\n#wemd {\n    padding: 30px 22px;\n    max-width: 677px;\n    margin: 0 auto;\n    font-family: -apple-system, BlinkMacSystemFont, \"Microsoft YaHei\", sans-serif;\n    color: #111;\n    background-color: transparent;\n    /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n    /* \u9876\u90E8\u7EA2\u84DD\u6761\u88C5\u9970 */\n    border-top: 8px solid #D32F2F;\n    border-bottom: 8px solid #1976D2;\n    word-break: break-word;\n}\n\n#wemd p {\n    margin: 24px 0;\n    line-height: 1.8;\n    text-align: justify;\n    color: #333;\n    font-size: 16px;\n}\n\n/* \u4E00\u7EA7\u6807\u9898 - \u7EA2\u8272\u51E0\u4F55\u5757 */\n#wemd h1 {\n    margin: 60px 0 40px;\n    text-align: left;\n}\n\n#wemd h1 .content {\n    font-size: 26px;\n    font-weight: 900;\n    color: #fff;\n    background: #D32F2F;\n    padding: 15px 25px;\n    display: inline-block;\n    /* \u7B80\u5355\u7684\u76F4\u89D2\u77E9\u5F62+\u786C\u9634\u5F71\uFF0C\u517C\u5BB9\u6027\u6700\u597D\u4E14\u6709\u529B */\n    box-shadow: 6px 6px 0 #111;\n    border: 2px solid #111;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* \u4E8C\u7EA7\u6807\u9898 - \u84DD\u8272\u5706\u5F62\u5F15\u5BFC */\n#wemd h2 {\n    margin: 50px 0 25px;\n    text-align: left;\n    display: flex;\n    align-items: center;\n}\n\n#wemd h2 .content {\n    font-size: 20px;\n    font-weight: bold;\n    color: #111;\n    position: relative;\n    padding-left: 20px;\n    border-left: 10px solid #1976D2;\n    /* \u84DD\u8272\u7AD6\u6761 */\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* \u4E09\u7EA7\u6807\u9898 - \u9EC4\u8272\u4E0B\u5212\u7EBF */\n#wemd h3 {\n    margin: 30px 0 15px;\n}\n\n#wemd h3 .content {\n    font-size: 18px;\n    font-weight: bold;\n    color: #111;\n    border-bottom: 5px solid #FBC02D;\n    display: inline-block;\n    padding-bottom: 2px;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* \u56DB\u7EA7\u6807\u9898 */\n#wemd h4 {\n    margin: 20px 0 10px;\n}\n\n#wemd h4 .content {\n    font-size: 16px;\n    font-weight: bold;\n    color: #1976D2;\n    background: #eee;\n    padding: 4px 8px;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* \u5F15\u7528 - \u51E0\u4F55\u6846 */\n#wemd .multiquote-1 {\n    margin: 30px 0;\n    padding: 20px;\n    background: #f9f9f9;\n    border: 2px solid #111;\n    box-shadow: 5px 5px 0 #D32F2F;\n}\n\n#wemd .multiquote-1 p {\n    color: #333;\n    margin: 0;\n    line-height: 1.7;\n}\n\n#wemd .multiquote-2 {\n    margin: 28px 0;\n    padding: 20px;\n    background: #fff;\n    border: 2px solid #111;\n    box-shadow: 4px 4px 0 #1976D2;\n}\n\n#wemd .multiquote-2 p {\n    color: #333;\n    margin: 0;\n}\n\n#wemd .multiquote-3 {\n    margin: 26px 0;\n    padding: 18px;\n    background: #fff;\n    border: 2px solid #111;\n    box-shadow: 3px 3px 0 #FBC02D;\n}\n\n#wemd .multiquote-3 p {\n    color: #333;\n    margin: 0;\n}\n\n/* \u5217\u8868 */\n#wemd ul {\n    list-style: square;\n    padding-left: 20px;\n    margin: 20px 0;\n    color: #D32F2F;\n}\n\n/* \u6709\u5E8F\u5217\u8868 - \u7C97\u9ED1\u6570\u5B57 */\n#wemd ol {\n    list-style: decimal;\n    padding-left: 20px;\n    margin: 20px 0;\n    color: #D32F2F;\n    font-weight: bold;\n}\n\n#wemd ul ul {\n    list-style-type: circle;\n    color: #1976D2;\n    margin-top: 8px;\n}\n\n#wemd ol ol {\n    list-style-type: lower-alpha;\n    color: #D32F2F;\n}\n\n#wemd li section {\n    color: #333;\n    font-weight: normal;\n}\n\n/* \u94FE\u63A5 - \u84DD\u8272\u80CC\u666F\u9AD8\u4EAE */\n#wemd a {\n    color: #111;\n    text-decoration: none;\n    background-color: rgba(25, 118, 210, 0.2);\n    border-bottom: 1px solid #1976D2;\n    padding: 0 2px;\n    font-weight: bold;\n}\n\n/* \u52A0\u7C97 - \u7EA2\u8272 */\n#wemd strong {\n    color: #D32F2F;\n    font-weight: 900;\n}\n\n/* \u659C\u4F53 - \u84DD\u8272 */\n#wemd em {\n    font-style: italic;\n    color: #1976D2;\n    font-weight: bold;\n}\n\n/* \u52A0\u7C97\u659C\u4F53 */\n#wemd em strong {\n    color: #D32F2F;\n    font-weight: 900;\n}\n\n/* \u9AD8\u4EAE - \u9EC4\u8272\u5757 */\n#wemd mark {\n    background: #FBC02D;\n    color: #000;\n    padding: 2px 6px;\n    font-weight: bold;\n}\n\n/* \u5220\u9664\u7EBF - \u7C97\u7EA2\u7EBF */\n#wemd del {\n    text-decoration: line-through;\n    text-decoration-thickness: 2px;\n    text-decoration-color: #D32F2F;\n    color: #666;\n}\n\n/* \u5206\u5272\u7EBF - \u7C97\u9ED1\u7EBF */\n#wemd hr {\n    margin: 40px 0;\n    border: none;\n    height: 4px;\n    background: #000;\n}\n\n/* \n * \u884C\u5185\u4EE3\u7801 - \u9EC4\u8272\u9AD8\u4EAE (\u4FEE\u590D\u91CD\u70B9) \n * \u4EAE\u9EC4\u80CC\u666F + \u9ED1\u8272\u6587\u5B57 + \u7C97\u4F53\n */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n    background: #FBC02D;\n    /* \u5305\u8C6A\u65AF\u9EC4 */\n    color: #000;\n    /* \u7EAF\u9ED1\u5B57 */\n    padding: 2px 6px;\n    margin: 0 4px;\n    font-size: 14px;\n    font-weight: bold;\n    font-family: sans-serif;\n    /* \u51E0\u4F55\u611F */\n}\n\n/* \u56FE\u7247 - \u9ED1\u6846\u786C\u9634\u5F71 */\n#wemd img {\n    display: block;\n    margin: 40px auto;\n    width: 100%;\n    border: 3px solid #111;\n    box-shadow: 6px 6px 0 #1976D2;\n    /* \u84DD\u8272\u786C\u9634\u5F71 */\n}\n\n#wemd figcaption {\n    margin-top: 10px;\n    text-align: center;\n    color: #111;\n    font-size: 14px;\n    font-weight: bold;\n    background: #FBC02D;\n    padding: 4px 8px;\n    display: inline-block;\n}\n\n/* \u4EE3\u7801\u5757 - \u6781\u7B80\u9ED1 */\n#wemd pre code.hljs {\n    background: #111;\n    color: #f5f5f5; /* \u9ED8\u8BA4\u4EAE\u8272\u6587\u5B57 */\n    padding: 20px;\n    border-radius: 0;\n    font-family: monospace;\n    border: 2px solid #111;\n}\n\n/* \u8BED\u6CD5\u9AD8\u4EAE\u989C\u8272\u8986\u76D6 - \u786E\u4FDD\u5728\u9ED1\u8272\u80CC\u666F\u4E0A\u53EF\u8BFB */\n#wemd pre code.hljs .hljs-keyword,\n#wemd pre code.hljs .hljs-selector-tag,\n#wemd pre code.hljs .hljs-built_in,\n#wemd pre code.hljs .hljs-name,\n#wemd pre code.hljs .hljs-tag {\n    color: #FBC02D; /* \u5305\u8C6A\u65AF\u9EC4 */\n}\n\n#wemd pre code.hljs .hljs-string,\n#wemd pre code.hljs .hljs-title,\n#wemd pre code.hljs .hljs-section,\n#wemd pre code.hljs .hljs-attribute,\n#wemd pre code.hljs .hljs-literal,\n#wemd pre code.hljs .hljs-template-tag,\n#wemd pre code.hljs .hljs-template-variable,\n#wemd pre code.hljs .hljs-type {\n    color: #D32F2F; /* \u5305\u8C6A\u65AF\u7EA2 */\n}\n\n#wemd pre code.hljs .hljs-comment,\n#wemd pre code.hljs .hljs-quote {\n    color: #888; /* \u7070\u8272\u6CE8\u91CA */\n}\n\n#wemd pre code.hljs .hljs-number,\n#wemd pre code.hljs .hljs-regexp,\n#wemd pre code.hljs .hljs-variable,\n#wemd pre code.hljs .hljs-params {\n    color: #1976D2; /* \u5305\u8C6A\u65AF\u84DD */\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u9EC4\u8272 */\n#wemd pre code:not(.hljs) {\n    color: #FBC02D;\n    background: #111;\n    border: 2px solid #111;\n}\n\n/* \u8868\u683C - \u7C97\u7EBF\u7F51\u683C */\n#wemd table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 30px 0;\n    border: 2px solid #111;\n}\n\n#wemd table tr th {\n    background: #1976D2;\n    color: #fff;\n    border: 1px solid #111;\n    padding: 10px;\n}\n\n#wemd table tr td {\n    border: 1px solid #111;\n    padding: 10px;\n    color: #333;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #1976D2;\n    font-weight: bold;\n}\n\n#wemd .footnotes-sep {\n    border-top: 2px solid #111;\n    margin-top: 40px;\n    padding-top: 20px;\n}\n\n#wemd .footnote-num {\n    font-weight: 900;\n    color: #fff;\n    background: #D32F2F;\n    padding: 2px 6px;\n    margin-right: 6px;\n}\n\n#wemd .footnote-item p {\n    color: #333;\n    font-size: 14px;\n}\n\n/* \u63D0\u793A\u5757 - \u5305\u8C6A\u65AF\u98CE\u683C */\n#wemd .callout {\n    margin: 30px 0;\n    padding: 20px;\n    background: #f9f9f9;\n    border: 2px solid #111;\n    box-shadow: 5px 5px 0 #FBC02D;\n    border-radius: 0;\n}\n\n#wemd .callout-title {\n    font-weight: 900;\n    margin-bottom: 10px;\n    text-transform: uppercase;\n    color: #111;\n    font-size: 16px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n    margin-right: 6px;\n}\n\n#wemd .callout-note { \n    border-left: 10px solid #1976D2; \n}\n\n#wemd .callout-tip { \n    border-left: 10px solid #FBC02D; \n}\n\n#wemd .callout-important { \n    border-left: 10px solid #1976D2; \n}\n\n#wemd .callout-warning { \n    border-left: 10px solid #FBC02D; \n}\n\n#wemd .callout-caution { \n    border-left: 10px solid #D32F2F; \n}\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
